    Bug 1982431 - Use ExtensionTestUtils.failOnSchemaWarnings() instead of changing the prefs directly. r=mkmelin


    This patch also restores the the `extensions.webextensions.uuids` preference.

    Differential Revision: https://phabricator.services.mozilla.com/D272925

diff --git a/mail/components/extensions/test/browser/browser_ext_commands_execute_browser_action.js b/mail/components/extensions/test/browser/browser_ext_commands_execute_browser_action.js
index ee0f62ed003..e8635e0dd13 100644
--- a/mail/components/extensions/test/browser/browser_ext_commands_execute_browser_action.js
+++ b/mail/components/extensions/test/browser/browser_ext_commands_execute_browser_action.js
@@ -108,12 +108,9 @@ add_setup(async () => {
   // throw but simply ignore this property, which is used by Firefox, but not by
   // us. However, by default, tests throw when deprecated properties are used,
   // which can be disabled by setting the following pref to false.
-  Services.prefs.setBoolPref(
-    "extensions.webextensions.warnings-as-errors",
-    false
-  );
+  ExtensionTestUtils.failOnSchemaWarnings(false);
   registerCleanupFunction(async () => {
-    Services.prefs.clearUserPref("extensions.webextensions.warnings-as-errors");
+    ExtensionTestUtils.failOnSchemaWarnings(true);
   });
 });

